private val refreshMutex = Mutex()
private var refreshDeferred: Deferred<String>? = null

suspend fun getValidToken(): String = refreshMutex.withLock {
    refreshDeferred?.await() ?: run {
        val deferred = externalScope.async { authApi.refreshToken() }
        refreshDeferred = deferred
        val token = deferred.await()
        refreshDeferred = null
        token
    }
}

fun verifySigningCertificate(context: Context): Boolean {
    val packageInfo = context.packageManager.getPackageInfo(
        context.packageName, PackageManager.GET_SIGNING_CERTIFICATES
    )
    val actualHash = sha256(packageInfo.signingInfo.apkContentsSigners[0].toByteArray())
    return actualHash == EXPECTED_SIGNING_HASH
}

